#!/usr/bin/env bash
set -euo pipefail
HERE="$(cd "$(dirname "$0")"&&pwd)"; . "$HERE/common.sh"; jc_fl_e2e_self_bound apply-schema 280s "$@"; jc_fl_e2e_test_phase_hold apply-schema; [ "$#" = 1 ]||jc_fl_e2e_fail 'usage: apply-schema.sh <run-id>'; jc_fl_e2e_reject_external; jc_fl_e2e_load_state "$1"; jc_fl_e2e_mysql_transport_owned||jc_fl_e2e_fail 'transport ownership mismatch'; [ "${MYSQL_SCHEMA_READY:-0}" = 0 ]||jc_fl_e2e_fail 'schema already ready'
mysql_root(){ jc_fl_e2e_docker exec -i "$MYSQL_CONTAINER_ID" mysql --defaults-extra-file=/tmp/root.cnf --port="$MYSQL_PORT" --batch --raw --skip-column-names "$@"; }; mysql_db(){ mysql_root "$DB_NAME"; }
PUBLISH_COMPLETE=0; STAGE="$RUN_DIR/.schema-publication.$$"; cleanup(){ local rc=$?; if [ "$PUBLISH_COMPLETE" != 1 ]; then if [ -f "$RUN_DIR/state.env" ]; then t="$RUN_DIR/.state.not-ready.$$"; awk '$0!~/^MYSQL_SCHEMA_READY=|^BASELINE_DIGEST=|^MIGRATION_MANIFEST_DIGEST=|^SCHEMA_DIGEST=|^GRANT_POLICY_DIGEST=|^OWNER_LABEL_DIGEST=/' "$RUN_DIR/state.env">"$t"; echo "MYSQL_SCHEMA_READY='0'">>"$t"; chmod 600 "$t"; mv "$t" "$RUN_DIR/state.env"; fi; rm -rf "$RUN_DIR/credentials" "$RUN_DIR/evidence/database-schema.json" "$RUN_DIR/evidence/schema-readiness.json"; fi; rm -rf "$STAGE" "$RUN_DIR/evidence/.database-schema."* "$RUN_DIR/evidence/.schema-readiness."* 2>/dev/null||true; return "$rc"; }; trap cleanup EXIT; trap 'exit 130' INT; trap 'exit 143' TERM; mkdir "$STAGE"; chmod 700 "$STAGE"
(cd "$JC_FL_E2E_ROOT/migrations"&&sha256sum -c FAIR_LAUNCH_SHA256SUMS); printf 'CREATE DATABASE `%s` CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;\n' "$DB_NAME"|mysql_root; echo "CREATE TABLE schema_migrations(filename VARCHAR(255) PRIMARY KEY,checksum CHAR(64) NOT NULL,status VARCHAR(16) NOT NULL,applied_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;"|mysql_db
while read -r c marked;do f="${marked#\*}"; printf "INSERT INTO schema_migrations VALUES('%s','%s','applied',NOW(6));\n" "$f" "$c"|mysql_db;done<"$JC_FL_E2E_ROOT/migrations/baseline/fair-launch-pre-2026-09-03-ledger.sha256"; mysql_db<"$JC_FL_E2E_ROOT/migrations/baseline/fair-launch-pre-2026-09-03.sql"
for f in 2026_09_03_fair_launch_project_model.sql 2026_09_04_fair_launch_ce_v2_governance.sql 2026_09_05_fair_launch_signing_release_control.sql 2026_09_06_fair_launch_action_execution.sql 2026_09_07_fair_launch_position_projection.sql;do { echo 'SET @JC_FAIR_LAUNCH_MIGRATION_APPROVED=1;';cat "$JC_FL_E2E_ROOT/migrations/$f";}|mysql_db;done
for f in 2026_09_08_fair_launch_local_e2e_binding.sql 2026_09_09_fair_launch_financial_projection_v3.sql 2026_09_10_fair_launch_governance_projection_v3.sql 2026_09_11_fair_launch_effect_lineage_v3.sql 2026_09_12_fair_launch_typed_ledger_v3.sql;do { echo 'SET @JC_FAIR_LAUNCH_LOCAL_E2E_APPROVED=1;';printf "SET @JC_FAIR_LAUNCH_LOCAL_E2E_RUN_ID='%s';\n" "$RUN_ID";cat "$JC_FL_E2E_ROOT/migrations/$f";}|mysql_db;done
POLICY="$JC_FL_E2E_ROOT/scripts/fair-launch/local-e2e/grant-policy.js"; if command -v node>/dev/null;then NODE_BIN="$(command -v node)";NODE_POLICY="$POLICY";elif command -v node.exe>/dev/null&&command -v wslpath>/dev/null;then NODE_BIN="$(command -v node.exe)";NODE_POLICY="$(wslpath -m "$POLICY")";else jc_fl_e2e_fail 'node required';fi
POLICY_DIR="$RUN_DIR/grants";mkdir -p "$POLICY_DIR";chmod 700 "$POLICY_DIR"; for role in runtime admin job ingest;do openssl rand -hex 32 >"$RUN_DIR/secrets/mysql-$role";chmod 600 "$RUN_DIR/secrets/mysql-$role";"$NODE_BIN" "$NODE_POLICY" expected "$DB_NAME" "$role">"$POLICY_DIR/expected-$role";done; "$NODE_BIN" "$NODE_POLICY" sql "$DB_NAME">"$POLICY_DIR/grants.sql";chmod 600 "$POLICY_DIR/"*
bash "$HERE/mysql-secret-helper.sh" emit-role-passwords "$RUN_DIR/secrets"|jc_fl_e2e_docker exec -i "$MYSQL_CONTAINER_ID" sh -c 'set -eu;umask 077;while IFS="$(printf "\t")" read -r role pw;do user="local_$role";printf "CREATE USER IF NOT EXISTS '\''%s'\''@'\''%%'\'' IDENTIFIED BY '\''%s'\'';\n" "$user" "$pw">>/tmp/users.sql;printf "[client]\nuser=%s\npassword=%s\nhost=127.0.0.1\nprotocol=tcp\n" "$user" "$pw">"/tmp/$user.cnf";chmod 600 "/tmp/$user.cnf";done;mysql --defaults-extra-file=/tmp/root.cnf --port="'$MYSQL_PORT'"</tmp/users.sql;rm /tmp/users.sql'>/dev/null
mysql_root<"$POLICY_DIR/grants.sql";for role in runtime admin job ingest;do printf "SHOW GRANTS FOR 'local_%s'@'%%';\n" "$role"|mysql_root|tr -d '\r'>"$POLICY_DIR/show-$role";"$NODE_BIN" -e "const p=require(process.argv[1]),f=require('fs');process.stdout.write(p.normalize(f.readFileSync(process.argv[2],'utf8').split(/\\r?\\n/)).join('\\n')+'\\n')" "$NODE_POLICY" "$(wslpath -m "$POLICY_DIR/show-$role" 2>/dev/null||echo "$POLICY_DIR/show-$role")">"$POLICY_DIR/actual-$role";diff -u "$POLICY_DIR/expected-$role" "$POLICY_DIR/actual-$role";done; bash "$HERE/grant-negative-test.sh" "$RUN_ID"
OBSERVED_MYSQL_UUID="$(echo 'SELECT LOWER(@@server_uuid);'|mysql_root)";OBSERVED_MYSQL_VERSION="$(echo 'SELECT VERSION();'|mysql_root)";[ "$OBSERVED_MYSQL_UUID|$OBSERVED_MYSQL_VERSION" = "$MYSQL_SERVER_UUID|$MYSQL_VERSION" ]||jc_fl_e2e_fail 'server changed';BASELINE="$(sha256sum "$JC_FL_E2E_ROOT/migrations/baseline/fair-launch-pre-2026-09-03.sql"|awk '{print $1}')";MIGRATION_DIGEST="$(sha256sum "$JC_FL_E2E_ROOT/migrations/FAIR_LAUNCH_SHA256SUMS"|awk '{print $1}')";SCHEMA_DIGEST="$(printf "SET SESSION group_concat_max_len=16777216; SELECT LOWER(SHA2(GROUP_CONCAT(CONCAT_WS('|',TABLE_NAME,COLUMN_NAME,ORDINAL_POSITION,COLUMN_TYPE,IS_NULLABLE,COALESCE(COLUMN_DEFAULT,'<NULL>'),COALESCE(COLLATION_NAME,'<NULL>'),EXTRA) ORDER BY BINARY TABLE_NAME,ORDINAL_POSITION SEPARATOR '\\n'),256)) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE();\n"|mysql_db)";GRANT_POLICY_DIGEST="$(cat "$POLICY_DIR"/actual-*|sha256sum|awk '{print $1}')";OWNER_DIGEST="$(printf '%s|%s|%s|host|network-not-used|%s|%s' "$RUN_ID" "$MYSQL_CONTAINER_ID" "$MYSQL_IMAGE_ID" "$MYSQL_ENDPOINT" "$DB_NAME"|sha256sum|awk '{print $1}')"
for role in runtime admin job ingest;do bash "$HERE/mysql-secret-helper.sh" write-profile "$RUN_DIR/secrets/mysql-$role" "$STAGE/mysql-$role.cnf" "$MYSQL_PORT" "$DB_NAME" "local_$role" "$RUN_ID";[ "$(bash "$HERE/mysql-secret-helper.sh" verify-profile "$STAGE/mysql-$role.cnf" "$MYSQL_PORT" "$MYSQL_SERVER_UUID" "$MYSQL_VERSION" "$DB_NAME" "local_$role")" = verified ]||jc_fl_e2e_fail 'staged profile failed';[ "${JC_FL_E2E_TEST_FAIL_AT:-}" != "after_profile_$role" ]||jc_fl_e2e_fail "injected after $role profile";done
[ "${JC_FL_E2E_TEST_FAIL_AT:-}" != after_profile_staging ]||jc_fl_e2e_fail 'injected after profile staging'; EVID_TMP="$RUN_DIR/evidence/.database-schema.$$"; [ "${JC_FL_E2E_TEST_FAIL_AT:-}" != before_schema_evidence ]||jc_fl_e2e_fail 'injected before schema evidence'; printf '{"authority":"TEST_ONLY_NOT_PRODUCTION_ADMITTED","runId":"%s","mysqlVersion":"%s","mysqlServerUuid":"%s","containerId":"%s","mysqlImageId":"%s","endpoint":"%s","database":"%s","transportDigest":"%s","baselineDigest":"%s","migrationManifestDigest":"%s","schemaDigest":"%s","grantPolicyDigest":"%s","ownerLabelDigest":"%s","status":"SCHEMA_STAGED_NOT_RUNTIME_ADMITTED"}\n' "$RUN_ID" "$MYSQL_VERSION" "$MYSQL_SERVER_UUID" "$MYSQL_CONTAINER_ID" "$MYSQL_IMAGE_ID" "$MYSQL_ENDPOINT" "$DB_NAME" "$MYSQL_TRANSPORT_DIGEST" "$BASELINE" "$MIGRATION_DIGEST" "$SCHEMA_DIGEST" "$GRANT_POLICY_DIGEST" "$OWNER_DIGEST">"$EVID_TMP";chmod 600 "$EVID_TMP";python3 -m json.tool "$EVID_TMP">/dev/null;[ "${JC_FL_E2E_TEST_FAIL_AT:-}" != during_schema_evidence ]||jc_fl_e2e_fail 'injected during schema evidence'
CREDENTIAL_DIR="$RUN_DIR/credentials"; [ ! -e "$CREDENTIAL_DIR" ]||jc_fl_e2e_fail 'credential dir exists'; mv "$STAGE" "$CREDENTIAL_DIR"; STAGE=''; mv "$EVID_TMP" "$RUN_DIR/evidence/database-schema.json"; [ "${JC_FL_E2E_TEST_FAIL_AT:-}" != after_schema_evidence ]||jc_fl_e2e_fail 'injected after schema evidence'; BASELINE_DIGEST="$BASELINE";MIGRATION_MANIFEST_DIGEST="$MIGRATION_DIGEST";GRANT_POLICY_DIGEST="$GRANT_POLICY_DIGEST";OWNER_LABEL_DIGEST="$OWNER_DIGEST"; [ "${JC_FL_E2E_TEST_FAIL_AT:-}" != before_final_marker ]||jc_fl_e2e_fail 'injected before marker'; python3 "$HERE/schema-readiness.py" build "$RUN_DIR" "$RUN_ID" "$MYSQL_TRANSPORT_DIGEST" "$MYSQL_IMAGE_ID" "$BASELINE" "$MIGRATION_DIGEST" "$SCHEMA_DIGEST" "$GRANT_POLICY_DIGEST" "$OWNER_DIGEST"; [ "${JC_FL_E2E_TEST_FAIL_AT:-}" != after_final_marker ]||jc_fl_e2e_fail 'injected after marker'; if [ "${JC_FL_E2E_TEST_HOLD_AT:-}" = after_final_marker ]; then echo HOLD_AFTER_FINAL_MARKER >&2; while :;do sleep 1;done;fi
tmp="$RUN_DIR/.state.schema.$$";awk '$0!~/^MYSQL_SCHEMA_READY=/' "$RUN_DIR/state.env">"$tmp";cat>>"$tmp" <<EOF
MYSQL_SCHEMA_READY='1'
BASELINE_DIGEST='$BASELINE'
MIGRATION_MANIFEST_DIGEST='$MIGRATION_DIGEST'
SCHEMA_DIGEST='$SCHEMA_DIGEST'
GRANT_POLICY_DIGEST='$GRANT_POLICY_DIGEST'
OWNER_LABEL_DIGEST='$OWNER_DIGEST'
EOF
chmod 600 "$tmp";mv "$tmp" "$RUN_DIR/state.env"; [ "${JC_FL_E2E_TEST_FAIL_AT:-}" != after_ready_state_rename ]||jc_fl_e2e_fail 'injected after ready state rename'; if [ "${JC_FL_E2E_TEST_HOLD_AT:-}" = after_ready_state_rename ]; then echo HOLD_AFTER_READY_STATE_RENAME >&2;while :;do sleep 1;done;fi; MYSQL_SCHEMA_READY=1; [ "${JC_FL_E2E_TEST_FAIL_AT:-}" != before_final_verification ]||jc_fl_e2e_fail 'injected before final verification'; if [ "${JC_FL_E2E_TEST_FAIL_AT:-}" = tamper_final_profile ]; then printf '\nunexpected-option=1\n'>>"$RUN_DIR/credentials/mysql-runtime.cnf"; fi; [ "${JC_FL_E2E_TEST_FAIL_AT:-}" != fail_final_verification ]&&jc_fl_e2e_mysql_profiles_ready||jc_fl_e2e_fail 'final readiness verification failed'; if [ "${JC_FL_E2E_TEST_HOLD_AT:-}" = after_final_verification ]; then echo HOLD_AFTER_FINAL_VERIFICATION >&2;while :;do sleep 1;done;fi; [ "${JC_FL_E2E_TEST_FAIL_AT:-}" != before_publish_complete ]||jc_fl_e2e_fail 'injected before publish complete'; PUBLISH_COMPLETE=1;trap - EXIT INT TERM;echo "Fair Launch local E2E schema ready: run_id=$RUN_ID database=$DB_NAME schema_digest=$SCHEMA_DIGEST credential_dir=$CREDENTIAL_DIR"
